  const requestRender = () => {
    if (frame === 0) frame = requestAnimationFrame(render);
  };

  const resize = () => {
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = size();
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    render();
  };

  const add = ({ tile, object }: StoredObject) => {
    if (object.type !== "Stroke") return;
    const frame = strokeFrame(tile, object);
    const entry = { tile, stroke: object, frame, path: strokeFramePath(object, frame) };
    const previous = entries.get(object.objectId);
    entries.set(object.objectId, entry);
    const rest = previous ? ordered.filter((other) => other !== previous) : ordered;
    const index = rest.findIndex((other) => other.stroke.objectId > object.objectId);
    ordered =
      index === -1 ? [...rest, entry] : [...rest.slice(0, index), entry, ...rest.slice(index)];
  };

  const eraseAt = (screen: Point) => {
    const { width, height } = size();
    const view = viewBounds(camera, width, height);
    const world = screenToWorld(camera, screen);
    for (const entry of ordered) {
      if (!isVisible(entry.stroke.bbox, view, camera.zoom)) continue;
      if (hitsStroke(entry.tile, entry.stroke, world, camera.zoom))
        source.erase(entry.stroke.objectId);
    }
  };

  const eraseTo = (screen: Point) => {
    const from = eraser ?? screen;
    const steps = Math.max(
      1,
      Math.ceil(Math.hypot(screen.x - from.x, screen.y - from.y) / ERASER_STEP_PX),
    );
    for (let step = 1; step <= steps; step++) {
      const t = step / steps;
      eraseAt({ x: from.x + (screen.x - from.x) * t, y: from.y + (screen.y - from.y) * t });
    }
    eraser = screen;
  };

  const pick = (screen: Point): Entry | undefined => {
    const { width, height } = size();
    const view = viewBounds(camera, width, height);
    const world = screenToWorld(camera, screen);
    return ordered.findLast(
      (entry) =>
        isVisible(entry.stroke.bbox, view, camera.zoom) &&
        hitsStroke(entry.tile, entry.stroke, world, camera.zoom),
    );
  };

  const startDrag = (screen: Point) => {
    const hit = pick(screen);
    selected = hit?.stroke.objectId;
    drag = hit && {
      objectId: hit.stroke.objectId,
      from: screenToWorld(camera, screen),
      dx: 0,
      dy: 0,
    };
  };

  const dragTo = (screen: Point) => {
    if (!drag) return;
    const world = screenToWorld(camera, screen);
    drag = { ...drag, dx: world.x - drag.from.x, dy: world.y - drag.from.y };
  };

  const drop = () => {
    const moved = drag;
    drag = undefined;
    const entry = moved && entries.get(moved.objectId);
    if (!moved || !entry || (moved.dx === 0 && moved.dy === 0)) return;
    const stored = translateStroke(entry.tile, entry.stroke, moved.dx, moved.dy);
    if (stored) source.commit(stored);
  };

  const discard = (objectId: string) => {
    if (selected === objectId && !source.objects.has(objectId)) selected = undefined;
    const entry = entries.get(objectId);
    if (!entry) return;
    entries.delete(objectId);
    ordered = ordered.filter((other) => other !== entry);
  };

  const onObjects = (changed: ReadonlySet<string>) => {
    for (const objectId of changed) {
      const stored = source.objects.get(objectId);
      if (stored) add(stored);
      else discard(objectId);
    }
    requestRender();
  };

  const onAwareness = () => {
    if (!awareness) return;
    cursors = [...awareness.getStates()].flatMap(([clientId, state]) => {
      if (clientId === awareness.clientID) return [];
      const cursor = remoteCursor(clientId, state);
      return cursor ? [cursor] : [];
    });
    requestRender();
  };

  const shareCursor = (screen: Point | undefined) => {
    if (!awareness) return;
    if (!screen) {
      awareness.setLocalStateField("cursor", null);
      return;
    }
    const now = performance.now();
    if (now - cursorSentAt < CURSOR_THROTTLE_MS) return;
    cursorSentAt = now;
    awareness.setLocalStateField("cursor", screenToWorld(camera, screen));
  };

  const updateView = () => {
    const { width, height } = size();
    source.view(viewBounds(camera, width, height), camera.zoom);
  };

  const settle = () => {
    clearTimeout(settleTimer);
    settleTimer = setTimeout(() => saveCamera(boardId, camera), 150);
    updateView();
  };

  const moveCamera = (next: Camera) => {
    if (!isCamera(next)) return;
    camera = next;
    requestRender();
    settle();
  };

  const commit = () => {
    if (!draft) return;
    const stored = finishDraft(draft);
    draft = undefined;
    if (!stored) return;
    source.commit(stored);
  };

  const localPoint = (event: PointerEvent | WheelEvent): Point => {
    const rect = canvas.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  const addPoint = (event: PointerEvent) => {
    if (!draft) return;
    const world = screenToWorld(camera, localPoint(event));
    const pressure = event.pointerType === "pen" ? Math.min(1, Math.max(0, event.pressure)) : 0.5;
    if (draft.points.length >= MAX_POINTS) {
      const last = draft.points.at(-1);
      const next: Draft = { ...draft, points: last ? [last] : [] };
      commit();
      draft = next;
    }
    draft.points.push([world.x, world.y, pressure]);
  };

  const pointerKind = (event: PointerEvent): PointerKind =>
    event.pointerType === "pen" || event.pointerType === "touch" ? event.pointerType : "mouse";

  const apply = (effects: readonly Effect[], event: PointerEvent) => {
    for (const effect of effects) {
      switch (effect.type) {
        case "StartStroke": {
          const tool = currentTool();
          if (tool.mode === "Select") {
            startDrag(localPoint(event));
            break;
          }
          if (tool.mode === "Eraser") {
            eraser = undefined;
            eraseTo(localPoint(event));
            break;
          }
          draft = startDraft(
            effect.secondary ? tool.secondary : tool.primary,
            tool.size,
            camera.zoom,
          );
          addPoint(event);
          break;
        }
        case "ExtendStroke": {
          const samples = event.getCoalescedEvents?.() ?? [];
          for (const sample of samples.length > 0 ? samples : [event]) {
            if (drag) dragTo(localPoint(sample));
            else if (eraser) eraseTo(localPoint(sample));
            else addPoint(sample);
          }
          break;
        }
        case "CommitStroke":
          eraser = undefined;
          drop();
          commit();
          break;
        case "DiscardStroke":
          eraser = undefined;
          drag = undefined;
          draft = undefined;
          break;
        case "Pan":
          moveCamera(pan(camera, effect.dx, effect.dy));
          break;
        case "Pinch":
          moveCamera(pinch(camera, effect.from, effect.to));
          break;
      }
    }
    if (effects.length > 0) requestRender();
  };

  const onPointerDown = (event: PointerEvent) => {
    event.preventDefault();
    canvas.setPointerCapture(event.pointerId);
    const effects = gestures.down(
      {
        pointerId: event.pointerId,
        kind: pointerKind(event),
        button: event.button,
        point: localPoint(event),
      },
      { panTool: currentTool().mode === "Pan", spaceDown },
    );
    apply(effects, event);
  };

  const onPointerMove = (event: PointerEvent) => {
    shareCursor(localPoint(event));
    apply(gestures.move(event.pointerId, localPoint(event)), event);
  };

  const onPointerUp = (event: PointerEvent) => {
    apply(gestures.up(event.pointerId), event);
  };

  const onPointerCancel = (event: PointerEvent) => {
    apply(gestures.cancel(event.pointerId), event);
  };

  const onWheel = (event: WheelEvent) => {
    event.preventDefault();
    const factor = wheelFactor(event.ctrlKey ? event.deltaY * 3 : event.deltaY, event.deltaMode);
    moveCamera(zoomAt(camera, localPoint(event), factor));
  };

  const onKey = (event: KeyboardEvent) => {
    if (event.type === "keydown" && (event.key === "Delete" || event.key === "Backspace")) {
      if (selected === undefined || currentTool().mode !== "Select") return;
      event.preventDefault();
      source.erase(selected);
      selected = undefined;
      requestRender();
      return;
    }
    if (event.code !== "Space") return;
    event.preventDefault();
    spaceDown = event.type === "keydown";
  };

  const onPointerLeave = () => shareCursor(undefined);

  const preventDefault = (event: Event) => event.preventDefault();

  const unobserve = source.objects.observe(onObjects);
  awareness?.on("change", onAwareness);

  const observer = new ResizeObserver(() => {
    resize();
    settle();
  });
  observer.observe(canvas);

  canvas.addEventListener("pointerdown", onPointerDown);
  canvas.addEventListener("pointermove", onPointerMove);
  canvas.addEventListener("pointerup", onPointerUp);
  canvas.addEventListener("pointercancel", onPointerCancel);
  canvas.addEventListener("pointerleave", onPointerLeave);
  canvas.addEventListener("wheel", onWheel, { passive: false });
  canvas.addEventListener("contextmenu", preventDefault);
  for (const type of BLOCKED_TOUCH_EVENTS) {
    canvas.addEventListener(type, preventDefault, { passive: false });
  }
  window.addEventListener("keydown", onKey);
  window.addEventListener("keyup", onKey);

  resize();
  onObjects(new Set(source.objects.keys()));
  onAwareness();
  updateView();

  return {
    dispose() {
      clearTimeout(settleTimer);
      cancelAnimationFrame(frame);
      observer.disconnect();
      canvas.removeEventListener("pointerdown", onPointerDown);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerup", onPointerUp);
      canvas.removeEventListener("pointercancel", onPointerCancel);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      canvas.removeEventListener("wheel", onWheel);
      canvas.removeEventListener("contextmenu", preventDefault);
      for (const type of BLOCKED_TOUCH_EVENTS) canvas.removeEventListener(type, preventDefault);
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("keyup", onKey);
      unobserve();
      awareness?.off("change", onAwareness);
      saveCamera(boardId, camera);
    },
  };
}
import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  fromTileLocal,
  nativeLevel,
  type Point,
  place,
  TILE_SIZE,
  type Tile,
  toTileLocal,
} from "@stallion/geometry";
import type { PencilSize, Stroke, Point as StrokePoint } from "@stallion/schema";
import getStroke, { type StrokeOptions } from "perfect-freehand";

export const PALETTE = ["#1f2328", "#e5484d", "#f76b15", "#30a46c", "#0090ff", "#8e4ec6"] as const;

export const PENCIL_SIZES: readonly PencilSize[] = ["Small", "Medium", "Large"];

const PENCIL_PX: Record<PencilSize, number> = { Small: 3, Medium: 8, Large: 20 };

export const MAX_POINTS = 4096;

export const strokeWorldWidth = (size: PencilSize, nativeZoom: number): number =>
  PENCIL_PX[size] * 2 ** (nativeZoom - 0.5);

const strokeOptions = (size: number, last: boolean): StrokeOptions => ({
  size,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.4,
  simulatePressure: false,
  last,
});

export const outlinePath = (
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): Path2D => {
  const outline = getStroke([...points], strokeOptions(size, last));
  const path = new Path2D();
  const [first, ...rest] = outline;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  path.closePath();
  return path;
};

export type Draft = {
  colour: number;
  size: PencilSize;
  nativeZoom: number;
  points: StrokePoint[];
};

export const startDraft = (colour: number, size: PencilSize, zoom: number): Draft => ({
  colour,
  size,
  nativeZoom: nativeLevel(zoom),
  points: [],
});

const draftBounds = (draft: Draft): BBox => {
  const margin = strokeWorldWidth(draft.size, draft.nativeZoom);
  const xs = draft.points.map((p) => p[0]);
  const ys = draft.points.map((p) => p[1]);
  return {
    minX: Math.min(...xs) - margin,
    minY: Math.min(...ys) - margin,
    maxX: Math.max(...xs) + margin,
    maxY: Math.max(...ys) + margin,
  };
};

const randomHex = (bytes: number): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");

const newObjectId = (): string => `${Date.now().toString(36).padStart(9, "0")}${randomHex(6)}`;

export const finishDraft = (draft: Draft): StoredObject | undefined => {
  if (draft.points.length === 0) return undefined;
  const bbox = draftBounds(draft);
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const stroke: Stroke = {
    type: "Stroke",
    objectId: newObjectId(),
    nativeZoom: draft.nativeZoom,
    bbox,
    colour: draft.colour,
    size: draft.size,
    points: draft.points.map(([x, y, pressure]) => {
      const local = toTileLocal(tile, { x, y });
      return [local.x, local.y, pressure];
    }),
  };
  return { tile, object: stroke };
};

export type StrokeFrame = { origin: Point; scale: number; points: StrokePoint[] };

// Path2D keeps float32, so points live relative to the stroke bbox, never the tile.
export const strokeFrame = (tile: Tile, stroke: Stroke): StrokeFrame => {
  const { bbox } = stroke;
  const origin = { x: bbox.minX, y: bbox.minY };
  const extent = Math.max(
    bbox.maxX - bbox.minX,
    bbox.maxY - bbox.minY,
    strokeWorldWidth(stroke.size, stroke.nativeZoom),
  );
  const scale = extent / TILE_SIZE;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    return [(world.x - origin.x) / scale, (world.y - origin.y) / scale, pressure];
  });
  return { origin, scale, points };
};

export const strokeFramePath = (stroke: Stroke, frame: StrokeFrame): Path2D =>
  outlinePath(frame.points, strokeWorldWidth(stroke.size, stroke.nativeZoom) / frame.scale, true);

export const draftScreenPath = (
  draft: Draft,
  toScreen: (world: Point) => Point,
  zoom: number,
): Path2D =>
  outlinePath(
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.size, draft.nativeZoom) * zoom,
    false,
  );

export const translateStroke = (
  tile: Tile,
  stroke: Stroke,
  dx: number,
  dy: number,
): StoredObject | undefined => {
  const bbox = {
    minX: stroke.bbox.minX + dx,
    minY: stroke.bbox.minY + dy,
    maxX: stroke.bbox.maxX + dx,
    maxY: stroke.bbox.maxY + dy,
  };
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    const local = toTileLocal(placed.tile, { x: world.x + dx, y: world.y + dy });
    return [local.x, local.y, pressure];
  });
  return { tile: placed.tile, object: { ...stroke, bbox, points } };
};
import type { Point } from "@stallion/geometry";

export type PointerKind = "mouse" | "pen" | "touch";

export type PointerDown = {
  pointerId: number;
  kind: PointerKind;
  button: number;
  point: Point;
};

export type Modifiers = { panTool: boolean; spaceDown: boolean };

export type Effect =
  | { type: "StartStroke"; secondary: boolean }
  | { type: "ExtendStroke" }
  | { type: "CommitStroke" }
  | { type: "DiscardStroke" }
  | { type: "Pan"; dx: number; dy: number }
  | { type: "Pinch"; from: readonly [Point, Point]; to: readonly [Point, Point] };

type Tracked = { point: Point; kind: PointerKind };

type State =
  | { mode: "Idle" }
  | { mode: "Draw"; pointerId: number }
  | { mode: "Pan"; pointerId: number }
  | { mode: "Pinch" };

export type Gestures = {
  down(event: PointerDown, modifiers: Modifiers): Effect[];
  move(pointerId: number, point: Point): Effect[];
  up(pointerId: number): Effect[];
  cancel(pointerId: number): Effect[];
};

const PRIMARY = 0;
const MIDDLE = 1;
const SECONDARY = 2;

export function createGestures(): Gestures {
  const pointers = new Map<number, Tracked>();
  let state: State = { mode: "Idle" };
  let penSeen = false;

  const touchIds = (): number[] =>
