mkdir -p ~/development/.tmp/stallion-flaky && cat > ~/development/.tmp/stallion-flaky/flaky.mjs <<'EOF'
import { mkdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { chromium, devices } from "playwright";

const label = process.argv[2] ?? "run";
const repeats = Number(process.argv[3] ?? 2);
const BASE = "http://100.104.44.51:5173/b/";
const POINTS = [2, 3, 5, 10, 30];
const SPACING = [0, 5, 16, 50];
const out = join(homedir(), "development", ".tmp", "stallion-flaky", label);
mkdirSync(out, { recursive: true });

const boardId = `flaky-${Date.now().toString(36)}`;
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ ...devices["Galaxy Tab S9"] });
const page = await context.newPage();
const errors = [];
page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
page.on("pageerror", (e) => errors.push(e.message));
await page.goto(BASE + boardId, { waitUntil: "load" });
await page.locator("canvas.surface").waitFor({ state: "visible" });
await page.waitForTimeout(1000);
const connection = await page.locator(".toolbar").innerText().catch(() => "?");

const count = () =>
  page.evaluate(
    (board) =>
      new Promise((resolve, reject) => {
        const r = indexedDB.open("stallion");
        r.onerror = () => reject(r.error);
        r.onsuccess = () => {
          const db = r.result;
          if (!db.objectStoreNames.contains("objects")) return resolve({ objects: 0, tiles: 0 });
          const tx = db.transaction([...db.objectStoreNames], "readonly");
          const res = {};
          const all = tx.objectStore("objects").getAll();
          all.onsuccess = () => (res.objects = all.result.filter((o) => o.boardId === board).length);
          const tiles = tx.objectStore("tiles").getAll();
          tiles.onsuccess = () => (res.tiles = tiles.result.filter((o) => o.boardId === board).length);
          tx.oncomplete = () => (db.close(), resolve(res));
        };
      }),
    boardId,
  );

const inkAt = async (clip) => {
  const buf = await page.screenshot({ clip });
  return page.evaluate(async (b64) => {
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const bm = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
    const c = new OffscreenCanvas(bm.width, bm.height);
    const ctx = c.getContext("2d");
    ctx.drawImage(bm, 0, 0);
    const d = ctx.getImageData(0, 0, bm.width, bm.height).data;
    let n = 0;
    for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] < 600) n++;
    return n;
  }, buf.toString("base64"));
};

const cdp = await context.newCDPSession(page);
const wait = (ms) => (ms > 0 ? page.waitForTimeout(ms) : Promise.resolve());
const touch = (type, p) =>
  cdp.send("Input.dispatchTouchEvent", {
    type,
    touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [],
  });

const vp = page.viewportSize();
const cols = 8;
const cellW = (vp.width - 80) / cols;
const cellH = 110;
const combos = [];
for (let r = 0; r < repeats; r++) for (const n of POINTS) for (const s of SPACING) combos.push({ n, s });

const results = [];
let prev = (await count()).objects;
for (const [i, { n, s }] of combos.entries()) {
  const x0 = 40 + (i % cols) * cellW + 10;
  const y0 = 140 + Math.floor(i / cols) * cellH + 20;
  const pts = Array.from({ length: n }, (_, k) => ({ x: x0 + (k / Math.max(1, n - 1)) * 60, y: y0 + (k % 2) * 8 }));
  const clip = { x: x0 - 20, y: y0 - 20, width: 100, height: 50 };
  await touch("touchStart", pts[0]);
  for (const p of pts.slice(1)) {
    await wait(s);
    await touch("touchMove", p);
  }
  await wait(s);
  await touch("touchEnd");
  await page.waitForTimeout(400);
  const now = (await count()).objects;
  const ink = await inkAt(clip);
  const stored = now > prev;
  results.push({ i, points: n, spacingMs: s, stored, ink });
  prev = now;
}
const shot = async (n, name) => {
  const idx = results.findIndex((r) => r.points === n);
  const x0 = 40 + (idx % cols) * cellW + 10;
  const y0 = 140 + Math.floor(idx / cols) * cellH + 20;
  const p = join(out, name);
  await page.screenshot({ path: p, clip: { x: x0 - 30, y: y0 - 30, width: 120, height: 70 } });
  return p;
};
const shots = [await shot(2, "two-point.png"), await shot(3, "three-point.png")];
await page.screenshot({ path: join(out, "full.png") });
const failed = results.filter((r) => !r.stored);
writeFileSync(join(out, "results.json"), JSON.stringify({ boardId, connection, results, errors }, null, 2));
console.log(`board ${boardId} connection "${connection.replace(/\s+/g, " ")}"`);
console.log(`failed ${failed.length}/${results.length}`);
for (const f of failed) console.log(`  FAIL points=${f.points} spacing=${f.spacingMs}ms ink=${f.ink}`);
console.log(`ink by points: ${POINTS.map((n) => `${n}:${results.filter((r) => r.points === n).map((r) => r.ink).join("/")}`).join(" ")}`);
console.log(`errors: ${errors.length ? errors.join(" | ") : "none"}`);
console.log(shots.join("\n"));
await browser.close();
EOF
cd ~/development/stallion && node ~/development/.tmp/stallion-flaky/flaky.mjs before 2

